import React from 'react';

interface AtividadeRecente {
  id: string;
  tipo: string;
  descricao: string;
  tempo: string;
  icone: string;
  cor: string;
}

interface RecentActivitiesProps {
  atividades: AtividadeRecente[];
}

const RecentActivities: React.FC<RecentActivitiesProps> = ({ atividades }) => {
  return (
    <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-xl rounded-2xl shadow-xl border border-white/20 dark:border-gray-700/50 p-6">
      <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-6 flex items-center">
        <span className="w-2 h-2 bg-orange-500 rounded-full mr-3"></span>
        Atividades Recentes
      </h3>
      <div className="space-y-4">
        {atividades.length === 0 ? (
          <div className="text-center py-8">
            <div className="text-gray-400 dark:text-gray-500 text-sm">
              Nenhuma atividade recente
            </div>
          </div>
        ) : (
          atividades.map((atividade) => (
            <div
              key={atividade.id}
              className="flex items-center space-x-4 p-3 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors duration-200"
            >
              <div className="w-10 h-10 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center flex-shrink-0">
                <span className="text-lg">{atividade.icone}</span>
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-gray-900 dark:text-white truncate">
                  {atividade.descricao}
                </p>
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  {atividade.tempo}
                </p>
              </div>
              <div className={`w-2 h-2 rounded-full ${atividade.cor.replace('text-', 'bg-')}`}></div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default RecentActivities;
